css:
@page {
    size: A4;
    margin: 0;
}

body {
    margin: 0;
    padding: 0;
    -webkit-print-color-adjust: exact;
}

.page {
    position: relative;
    width: 210mm;
    min-height: auto;
    background-color: #fff;
    font-family: 'Arial', sans-serif;
    padding-bottom: 80px;
    box-sizing: border-box;
}

.header-top {
    background-color: #006363;
    height: 85px;
    padding: 10px 40px;
    display: flex;
    align-items: center;
}

.logo-text h1 { margin-top: 30px; font-size: 32px; letter-spacing: 0px; line-height: 0.2; }
.logo-text p { margin-bottom: 10px; font-size: 10px; letter-spacing: 0px; }

.header-bar {
    background-color: #00ced1;
    height: 22px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 30px;
    color:#fff;
    font-size: 10px;
    font-weight: bold;
}



.footer-area {
    position: relative;
    width: 100%;
    text-align: center;
    padding-bottom: 4px;
    margin-top: 20px;
}

.head-office { color: #007979; font-weight: bold; margin: 0; font-size: 12px; }
.address, .contact { color: #007979; margin: 2px 0; font-size: 10px; }
.footer-bottom-bar {
    height: 12px;
    background-color: #006363;
    margin-top: 10px;
    /*clip-path: polygon(0 0, 100% 0, 100% 100%, 5% 100%);*/
}

.content {
    position: relative;
    z-index: 10;
    padding: 20px 25mm;
    margin-top: 20px;
    font-family: "Times New Roman", serif;
    text-align: justify;
}

.content h2 { text-align: center; margin-bottom: 30px; font-size: 22px; font-weight: bold; }
.content p { font-size: 18px; line-height: 1.6; margin-bottom: 15px; text-indent: 40px; }
.details p { text-indent: 0; margin-bottom: 5px; }
.signature { margin-bottom: 100px; }
